export type GmailPause = {
  code:
    | "RECONNECT_REQUIRED"
    | "OWNER_THROTTLE"
    | "PROVIDER_DAILY_LIMIT"
    | "DOMAIN_POLICY"
    | "PROJECT_COOLDOWN";
  until: string | null;
};
export function gmailPauseMessage(pause: GmailPause) {
  switch (pause.code) {
    case "RECONNECT_REQUIRED":
      return "Reconnect Gmail to restore sending permission. Cancelled emails stay cancelled.";
    case "DOMAIN_POLICY":
      return "Your Google Workspace policy blocks Gmail sending. Ask your workspace administrator to allow Mailloop, then reconnect Gmail.";
    case "PROVIDER_DAILY_LIMIT":
      return "Gmail's sending limit has paused sending. This is separate from your Mailloop allowance.";
    case "OWNER_THROTTLE":
      return "Gmail is temporarily limiting requests. Queued emails will resume after the provider cooldown.";
    case "PROJECT_COOLDOWN":
      return "Gmail has paused the application's provider quota. Queued emails will resume after the provider cooldown.";
  }
}

export function sendingPause(
  user: {
    gmailPauseReason?: Exclude<GmailPause["code"], "PROJECT_COOLDOWN"> | null;
    gmailPauseUntil?: Date | null;
  },
  control: { gmailProjectPauseUntil?: Date | null } | null,
  now = new Date(),
) {
  if (
    user.gmailPauseReason === "RECONNECT_REQUIRED" ||
    user.gmailPauseReason === "DOMAIN_POLICY"
  )
    return { code: user.gmailPauseReason, until: null };
  if (control?.gmailProjectPauseUntil && control.gmailProjectPauseUntil > now)
    return {
      code: "PROJECT_COOLDOWN" as const,
      until: control.gmailProjectPauseUntil,
    };
  if (
    user.gmailPauseReason &&
    (!user.gmailPauseUntil || user.gmailPauseUntil > now)
  )
    return { code: user.gmailPauseReason, until: user.gmailPauseUntil ?? null };
  return null;
}
